<script lang="ts">
	import { data } from '#lib/stores/data';
	import { recordData } from '#lib/workflow';
	import { Boxes, GlassWater, PackageSearch, Ruler, Search, TriangleAlert } from '@lucide/svelte';
	let query=$state('');
	function materials(){const map=new Map<string,any>();for(const record of Object.values($data.drawings)){const d=recordData(record),p=d.production||{};for(const cut of (p.cuts||d.cuts||[])){const code=cut.profileCode||cut.profile_code;const row=map.get(code)||{code,name:cut.profileName||cut.profile_name,meters:0,pieces:0,bars:0};row.meters+=Number(cut.length||cut.length_mm||0)*Number(cut.quantity||0)/1000;row.pieces+=Number(cut.quantity||0);map.set(code,row)}for(const bar of (p.bars||d.bars||[])){const code=bar.profileCode||bar.profile_code;if(map.has(code))map.get(code).bars+=1}}return [...map.values()].filter(x=>`${x.code} ${x.name}`.toLocaleLowerCase('tr-TR').includes(query.toLocaleLowerCase('tr-TR'))).sort((a,b)=>b.meters-a.meters)}
	function glassTotal(){return Object.values($data.drawings).reduce((s,r)=>s+Number(recordData(r).production?.glassArea||0),0)}
</script>
<svelte:head><title>Stok İhtiyacı | Tayfun Yapı</title></svelte:head>
<div class="page"><header><div><span>ATÖLYE</span><h1>Stok ve Malzeme İhtiyacı</h1><p>Kaydedilen işlerden oluşan profil, cam ve aksesuar ihtiyacı.</p></div></header><section class="cards"><div><Boxes/><span>Profil çeşidi<strong>{materials().length}</strong></span></div><div><Ruler/><span>Toplam profil<strong>{materials().reduce((s,x)=>s+x.meters,0).toFixed(1)} m</strong></span></div><div><PackageSearch/><span>Standart boy<strong>{materials().reduce((s,x)=>s+x.bars,0)} adet</strong></span></div><div><GlassWater/><span>Cam ihtiyacı<strong>{glassTotal().toFixed(2)} m²</strong></span></div></section><label class="search"><Search size={17}/><input bind:value={query} placeholder="Profil kodu veya malzeme ara"/></label><section class="table"><div class="tr head"><span>Profil kodu</span><span>Malzeme</span><span>Kesim adedi</span><span>Toplam metre</span><span>Gerekli boy</span><span>Durum</span></div>{#each materials() as item}<div class="tr"><code>{item.code}</code><strong>{item.name}</strong><span>{item.pieces}</span><span>{item.meters.toFixed(2)} m</span><span>{item.bars} adet</span><span class="need"><TriangleAlert size={14}/>Kontrol et</span></div>{:else}<div class="empty">Kaydedilmiş üretim malzemesi bulunamadı.</div>{/each}</section><p class="note"><TriangleAlert size={15}/>Bu ekran kaydedilen projelerin ihtiyacını gösterir. Fiziksel stok miktarı girildiğinde eksik malzemeler otomatik hesaplanacaktır.</p></div>
<style>
	.page{max-width:1380px;margin:auto;padding:30px}header span{font-size:10px;font-weight:800;color:#0f7c80;letter-spacing:1px}h1{font-size:28px;margin:2px 0}header p{margin:0;color:#78838e}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:20px 0 12px}.cards>div{display:flex;align-items:center;gap:12px;padding:15px;background:#fff;border:1px solid #dfe4e8;border-radius:7px;color:#0f7c80}.cards span,.cards strong{display:block}.cards span{font-size:10px;color:#7d8993}.cards strong{font-size:19px;color:#24313a}.search{height:42px;display:flex;align-items:center;gap:8px;background:#fff;border:1px solid #d9dfe4;border-radius:6px;padding:0 12px;margin-bottom:10px;color:#7d8993}.search input{border:0;outline:0;width:100%;font:inherit}.table{background:#fff;border:1px solid #dfe4e8;border-radius:7px;overflow:hidden}.tr{display:grid;grid-template-columns:130px 1fr 120px 130px 120px 120px;gap:10px;align-items:center;padding:11px 14px;border-bottom:1px solid #edf0f2}.tr.head{background:#f7f9fa;font-size:10px;color:#78838e;font-weight:800}.tr code{color:#0f7c80;font-weight:800}.need{display:flex;align-items:center;gap:5px;color:#c36e0b;font-size:10px;font-weight:800}.empty{padding:50px;text-align:center;color:#84909a}.note{display:flex;align-items:center;gap:7px;font-size:11px;color:#78838e;margin-top:10px}
	@media(max-width:900px){.cards{grid-template-columns:1fr 1fr}.table{overflow:auto}.tr{min-width:850px}}
	@media(max-width:650px){.page{padding:18px 12px 90px}h1{font-size:23px}.cards>div{padding:12px}.cards strong{font-size:16px}}
</style>
